  const aliases: Record<string, string> = {
    torrent: 'qbittorrent',
    bambu: 'bambulab',
    bambuconnect: 'bambulab',
    'bambu-connect': 'bambulab',
    'bambu-lab': 'bambulab',
    octoeverywhere: 'bambulab',
    envoyproxy: 'envoy',
    'envoy-proxy': 'envoy',
    'envoy-gateway': 'envoy',
    envoygateway: 'envoy',
    'nginx-ingress': 'nginx',
    'ingress-nginx': 'nginx',
    certmanager: 'cert-manager',
    externalsecrets: 'external-secrets',
    'metal-lb': 'metallb',
    k8s: 'kubernetes',
    fluxcd: 'flux',
    dolphin: 'deploystackr'
  };

  function resolveIcon(iconKey: string, serviceKey: string): { viewBox: string; path?: string; raw?: string } | null {
    const normalize = (k: string) => k.trim().toLowerCase().replace(/[-_\s]/g, '');

    const candidates = [
      iconKey.trim().toLowerCase(),
      aliases[iconKey.trim().toLowerCase()] || '',
      normalize(iconKey),
      aliases[normalize(iconKey)] || '',
      serviceKey.trim().toLowerCase(),
      aliases[serviceKey.trim().toLowerCase()] || '',
      normalize(serviceKey),
      aliases[normalize(serviceKey)] || ''
    ].filter(Boolean);

    for(const key of candidates) {
      if(builtInIcons[key]) {
        const item = builtInIcons[key];
        if(typeof item === 'string') {
          return {viewBox: '0 0 24 24', path: item};
        }
        return item;
      }
    }
    return null;
  }

  let isRawSvg = $derived(icon.trim().startsWith('<svg'));
  let isUrl = $derived(icon.startsWith('http://') || icon.startsWith('https://') || icon.startsWith('/') || icon.startsWith('data:'));
  let resolvedIcon = $derived(resolveIcon(icon, name));
</script>

{#if isRawSvg}
  <span class="raw-svg monochrome-svg" style="width: {size}px; height: {size}px;">
    {@html icon}
  </span>
{:else if isUrl}
  <span
    class="monochrome-logo-mask"
    style="width: {size}px; height: {size}px; -webkit-mask-image: url('{icon}'); mask-image: url('{icon}');"
    title={name}
  ></span>
{:else if resolvedIcon}
  <svg
    width={size}
    height={size}
    viewBox={resolvedIcon.viewBox}
    fill="currentColor"
    class="custom-svg-icon"
  >
    {#if resolvedIcon.raw}
      {@html resolvedIcon.raw}
    {:else if resolvedIcon.path}
      <path d={resolvedIcon.path} />
    {/if}
  </svg>
{:else if icon}
  <span class="material-symbols-outlined icon-symbol" style="font-size: {size}px;">
    {icon}
  </span>
{:else}
  <!-- Default code/layer icon -->
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    fill="currentColor"
    class="custom-svg-icon"
  >
    <path d={builtInIcons.deployed_code as string} />
  </svg>
{/if}

<style>
  .raw-svg {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: currentColor;
  }

  .monochrome-svg :global(svg) {
    width: 100%;
    height: 100%;
  }

  .monochrome-svg :global(path),
  .monochrome-svg :global(circle),
  .monochrome-svg :global(polygon),
  .monochrome-svg :global(rect) {
    fill: currentColor !important;
  }

  .monochrome-logo-mask {
    display: inline-block;
    vertical-align: middle;
    flex-shrink: 0;
    background-color: currentColor;
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
  }

  .custom-svg-icon {
    display: inline-block;
    vertical-align: middle;
    flex-shrink: 0;
    color: currentColor;
  }

  .icon-symbol {
    display: inline-block;
    vertical-align: middle;
    line-height: 1;
    font-size: 20px;
    font-variation-settings: 'FILL' 0, 'wght' 500, 'GRAD' 0, 'opsz' 24;
  }
</style>
